			// Dated/custom GPT-4.x ids (gpt-4o-2024-08-06, gpt-4.1-mini, …) are sampling-only.
			return isOpenAiSamplingModelId(modelId) ? OPENAI_SAMPLING : OPENAI_REASONING_CUSTOM;
		case 'azure':
			return AZURE_CUSTOM;

